#!/bin/sh
# SAZ1051 / OS05L10 sensor init-table replay over I2C.
# 背景: 用户态 libsns_os05l10.so 的 cis_write_reg 路径写不进 sensor
#   (i2c 写不落地且不报错) -> sensor 停在出厂默认值 -> MIPI 无数据 -> VI 无帧。
#   8-bit 寄存器地址 + 0xFD bank 切换 (由表内 0xfd 条目给出)。
#   实证: 重放后 /proc/umap/mipi_rx 的 cil_clk_cur_stat 变 HS_LP00,
#   mipi_vc0_w/h = 2880/1620, ISP int_cnt 30fps, VENC 出货。
PATH=/usr/sbin:/usr/bin:/bin:/sbin; export PATH
I2C=i2ctransfer
W() { $I2C -y 0 w2@0x3c $1 $2; }
W 0xfd 0x00          # bank 0
W 0x03 0x01          # software reset
sleep 1

